"""Kitchen Sink page: containers with pages (ToolBox: an accordion; PageFrame: pages
without tabs, switched from a ListBox) and a ScrollPanel, whose controls scroll. In the
designer, click a ToolBox's headers, or use Previous Page / Next Page, to edit each page."""

from vp6 import *


class pgPages(Form):
    # region VP6 Designer - generated by the form designer, do not edit
    def InitializeComponent(self):
        self.Caption = 'Pages and scrolling panels'
        self.Width = 640
        self.Height = 440
        self.tbxTools = ToolBox(self, Left=16, Top=16, Width=200, Height=300,
                                Pages=['&Shapes|shapes|What to draw', '&Colors|colors|What color', '&Note|note|A note to keep'],
                                TabIndex=1)
        self.lstShapes = ListBox(self.tbxTools, Page=0, Left=8, Top=8, Width=170, Height=110,
                                 List=['Circle', 'Square', 'Triangle'], TabIndex=2)
        self.optRed = OptionButton(self.tbxTools, Page=1, Caption='Red', Left=8, Top=8, Width=120,
                                   Height=25, Value=True, TabIndex=3)
        self.optBlue = OptionButton(self.tbxTools, Page=1, Caption='Blue', Left=8, Top=36,
                                    Width=120, Height=25, TabIndex=4)
        self.txtNote = TextBox(self.tbxTools, Page=2, MultiLine=True,
                               Text='Pages hold controls, like Frames', Left=8, Top=8, Width=170,
                               Height=100, TabIndex=5)
        self.lblToolBox = Label(self, Caption='', Left=16, Top=324, Width=200, Height=60,
                                WordWrap=True, TabIndex=6)
        self.lstSteps = ListBox(self, Left=232, Top=16, Width=150, Height=90,
                                List=['1. Your name', '2. Your town', '3. Done'], TabIndex=7,
                                ToolTipText='Choose a step: the PageFrame shows its page')
        self.pgfSteps = PageFrame(self, Left=392, Top=16, Width=232, Height=90, PageCount=3,
                                  BorderStyle=1, TabIndex=8)
        self.lblName = Label(self.pgfSteps, Page=0, Caption='Your name:', Left=8, Top=12,
                             Width=200, Height=22, TabIndex=9)
        self.txtName = TextBox(self.pgfSteps, Page=0, Text='', Left=8, Top=40, Width=200,
                               Height=25, TabIndex=10)
        self.lblTown = Label(self.pgfSteps, Page=1, Caption='Your town:', Left=8, Top=12,
                             Width=200, Height=22, TabIndex=11)
        self.txtTown = TextBox(self.pgfSteps, Page=1, Text='', Left=8, Top=40, Width=200,
                               Height=25, TabIndex=12)
        self.lblDone = Label(self.pgfSteps, Page=2, Caption='All done!', Left=8, Top=12, Width=210,
                             Height=60, WordWrap=True, TabIndex=13)
        self.lblFrame = Label(self, Caption='', Left=232, Top=112, Width=392, Height=22,
                              TabIndex=14)
        self.scpBig = ScrollPanel(self, Left=232, Top=144, Width=392, Height=220, TabIndex=15)
        self.cmdNear = CommandButton(self.scpBig, Caption='Near', Left=16, Top=16, Width=97,
                                     Height=33, TabIndex=16)
        self.cmdMiddle = CommandButton(self.scpBig, Caption='In the middle', Left=420, Top=260,
                                       Width=120, Height=33, TabIndex=17)
        self.cmdFar = CommandButton(self.scpBig, Caption='Far away', Left=900, Top=600, Width=97,
                                    Height=33, TabIndex=18)
        self.cmdShowFar = CommandButton(self, Caption='&Show the far button', Left=232, Top=372,
                                        Width=180, Height=33, TabIndex=19,
                                        ToolTipText='EnsureVisible: the ScrollPanel scrolls to it')
        self.lblScroll = Label(self, Caption='', Left=424, Top=378, Width=200, Height=22,
                               TabIndex=20)
    # endregion

    # --- ToolBox ----------------------------------------------------------------------
    def tbxTools_PageChange(self):
        page = self.tbxTools.SelectedItem
        self.lblToolBox.Caption = (f"PageChange: page {self.tbxTools.CurrentPage} "
                                   f"({page.Caption.replace('&', '')}: {page.ToolTipText})")

    def lstShapes_Click(self):
        color = "red" if self.optRed.Value else "blue"
        self.lblToolBox.Caption = f"A {color} {self.lstShapes.Text.lower()}"

    # --- PageFrame ----------------------------------------------------------------------
    def lstSteps_Click(self):
        self.pgfSteps.CurrentPage = self.lstSteps.ListIndex  # (both count from 0)

    def pgfSteps_PageChange(self):
        page = self.pgfSteps.CurrentPage
        if page == 2:
            self.lblDone.Caption = f"All done, {self.txtName.Text or '?'} from " \
                                   f"{self.txtTown.Text or '?'}!"
        self.lblFrame.Caption = f"PageChange: page {page} of {self.pgfSteps.PageCount}"

    # --- ScrollPanel ----------------------------------------------------------------------
    def scpBig_Scroll(self):
        self.lblScroll.Caption = f"Scroll: {self.scpBig.ScrollLeft}, {self.scpBig.ScrollTop}"

    def cmdShowFar_Click(self):
        self.scpBig.EnsureVisible(self.cmdFar)

    def cmdFar_Click(self):
        self.scpBig.ScrollLeft = self.scpBig.ScrollTop = 0  # back to the start


if __name__ == "__main__":
    run(pgPages)
